//! Excluded actual-gallery controlled client/host cross-page navigation.
use super::grid_worklist_review::gallery_worklist;
use super::host_paged_grid_review::gallery_host;
use dioxus::prelude::*;
use dioxus_ix::*;

#[component]
pub fn GridPageNavigationPreview() -> Element {
    #[cfg(all(feature = "desktop", not(target_arch = "wasm32")))]
    let window = dioxus::desktop::window();
    rsx! {
        style { {STYLES} }
        style { {gallery_worklist::STYLES} }
        IxTheme { class:"grid-page-navigation-review",
            gallery_worklist::GridWorklistExample {}
            gallery_host::HostPagedGridExample {}
            div { onmounted:move |_| {
                #[cfg(all(feature="desktop",not(target_arch="wasm32")))]
                {let window=window.clone();spawn(async move {
                    let query=crate::dom_query::eval(NATIVE_GRID_PAGE_NAVIGATION_CHECK);let _=query.send("gridpagenavigation");
                    match query.join::<serde_json::Value>().await {
                        Ok(value)if value["ok"]==true=>{println!("Dioxus native Grid page navigation: {value}");window.close();}
                        value=>{eprintln!("Dioxus native Grid page navigation failed: {value:?}");std::process::exit(1);}
                    }
                });spawn(async move {futures_timer::Delay::new(std::time::Duration::from_secs(45)).await;eprintln!("Grid page navigation native replay timed out");std::process::exit(1);});}
            } }
        }
    }
}
const STYLES: &str = "body{margin:0}.grid-page-navigation-review{box-sizing:border-box;min-height:100vh;padding:24px}@media(max-width:600px){.grid-page-navigation-review{padding:16px}}";

#[cfg(all(feature = "desktop", not(target_arch = "wasm32")))]
const NATIVE_GRID_PAGE_NAVIGATION_CHECK: &str = r#"
let snapshots={};
try{
 await dioxus.recv();
 const specs=[{name:'client',prefix:'worklist',root:'grid-worklist',label:'Maintenance worklist',row:'worklist-',last:95,lastColumn:'ticket',groupPage:2,lastNormal:93,maintenancePage:5},{name:'host',prefix:'host-paged',root:'host-paged-grid',label:'Host-paged equipment',row:'host-equipment-',last:136,lastColumn:'owner',groupPage:3,lastNormal:135,maintenancePage:7}];
 const get=(s,name)=>document.getElementById(s.prefix+'-'+name),host=s=>document.getElementById(s.root),grid=s=>host(s)?.querySelector('[aria-label="'+s.label+'"][role="grid"],[aria-label="'+s.label+'"][role="treegrid"]'),id=(s,n)=>s.row+String(n).padStart(3,'0'),row=(s,n)=>grid(s)?.querySelector('[data-row-id="'+id(s,n)+'"]'),cell=(s,n,column)=>row(s,n)?.querySelector('[role="gridcell"][data-column-id="'+column+'"]'),pg=s=>get(s,s.name==='client'?'pagination-status':'status'),status=s=>get(s,'status'),control=(s,label)=>host(s)?.querySelector('nav[aria-label="'+s.label+' pages"] [aria-label="'+label+'"]'),toggle=(s,value)=>grid(s)?.querySelector('.ix-data-grid-group[data-group-column="status"][data-group-value="'+value+'"] .ix-data-grid-group-toggle');
 const assert=(value,label)=>{if(!value)throw Error(label)},wait=async(label,predicate)=>{for(let i=0;i<220;i++){if(predicate())return;await new Promise(resolve=>setTimeout(resolve,20))}throw Error(label+'; active='+(document.activeElement?.outerHTML.slice(0,350)))};
 const key=(node,value)=>node.dispatchEvent(new KeyboardEvent('keydown',{key:value,code:value,bubbles:true,cancelable:true})),focus=async node=>{assert(node,'actual current focus target exists');node.scrollIntoView({block:'nearest',inline:'nearest'});node.focus();await wait('actual native focus',()=>document.activeElement===node)};
 const focusRow=async(s,n,column)=>wait('current accepted '+s.name+' row/lane '+n+'/'+column,()=>{const a=document.activeElement;return host(s).contains(a)&&a.closest('[data-row-id]')?.dataset.rowId===id(s,n)&&(column==='selection'?a.getAttribute('role')==='checkbox':a.dataset.columnId===column)});
 const page=async(s,value)=>{const n=control(s,'Page selection');Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(n,String(value+1));n.dispatchEvent(new Event('input',{bubbles:true}));key(n,'Enter');await wait('actual accepted page '+s.name+value,()=>pg(s).dataset.page===String(value))};
 const mode=async s=>{get(s,'grouping').value='status';get(s,'grouping').dispatchEvent(new Event('change',{bubbles:true}));await wait('actual Status grouping '+s.name,()=>grid(s).getAttribute('role')==='treegrid'&&pg(s).dataset.page==='0')};
 for(const s of specs){await wait('actual new option ready '+s.name,()=>get(s,'navigate-across-pages'));assert(!get(s,'navigate-across-pages').checked,'new navigation defaults off');if(s.name==='client'){get(s,'pagination').click();await wait('manual client12',()=>pg(s).dataset.pageSize==='12');get(s,'readonly').click();await wait('actual readonly Grid applied',()=>cell(s,0,'asset').getAttribute('aria-readonly')==='true')}row(s,1).querySelector('[role="checkbox"]').click();await wait('accepted source selection before page entry',()=>status(s).dataset.selected==='1'&&row(s,1).getAttribute('aria-selected')==='true');get(s,'navigate-across-pages').click();await wait('opt-in accepted '+s.name,()=>pg(s).dataset.navigateAcrossPages==='true');await focus(cell(s,11,'owner'));key(document.activeElement,'ArrowDown');await focusRow(s,12,'owner');assert(pg(s).dataset.page==='1','next page admitted');key(document.activeElement,'ArrowUp');await focusRow(s,11,'owner');key(document.activeElement,'PageDown');await wait('viewport step extends beyond first next-row boundary',()=>host(s).contains(document.activeElement)&&Number(document.activeElement?.closest('[data-row-id]')?.dataset.rowId.split('-').at(-1))>12);assert(document.activeElement.dataset.columnId==='owner','PageDown preserves cell lane');const stepped=document.activeElement.closest('[data-row-id]').dataset.rowId;key(document.activeElement,'PageUp');await focusRow(s,11,'owner');key(document.activeElement,'End');await focusRow(s,s.last,s.lastColumn);key(document.activeElement,'Home');await focusRow(s,0,'asset');await focus(row(s,11).querySelector('[role="checkbox"]'));key(document.activeElement,'ArrowDown');await focusRow(s,12,'selection');key(document.activeElement,'Home');await focusRow(s,0,'selection');key(document.activeElement,'End');await focusRow(s,s.last,'selection');assert(status(s).dataset.selected==='1'&&status(s).dataset.saved==='0'&&!host(s).querySelector('.ix-data-grid-editor:not([readonly])'),'navigation does not select or edit');if(s.name==='client')get(s,'readonly').click();snapshots[s.name+'Flat']={stepped,page:{...pg(s).dataset}}}
 for(const s of specs){await mode(s);await page(s,1);await focus(cell(s,69,'owner'));key(document.activeElement,'ArrowDown');await focusRow(s,72,'owner');key(document.activeElement,'ArrowUp');if(s.name==='host'){await wait('independent host Up reaches ordinary local Normal header',()=>document.activeElement===toggle(s,'Normal'));key(document.activeElement,'ArrowUp')}await focusRow(s,69,s.name==='host'?'selection':'owner');await page(s,s.groupPage);toggle(s,'Warning').click();await wait('actual Warning collapsed',()=>toggle(s,'Warning').getAttribute('aria-expanded')==='false');await focus(cell(s,s.lastNormal,'owner'));key(document.activeElement,'ArrowDown');await wait('real closed Warning header remains a focus destination',()=>document.activeElement===toggle(s,'Warning'));key(document.activeElement,'ArrowDown');await wait('closed continuation pages reach new Maintenance header',()=>document.activeElement===toggle(s,'Maintenance'));assert(pg(s).dataset.page===String(s.maintenancePage),'Maintenance header uses accepted owning page');key(document.activeElement,'ArrowDown');await focusRow(s,2,'selection');assert(status(s).dataset.selected==='1','group traversal preserves selected source');snapshots[s.name+'Grouped']={...pg(s).dataset}}
 for(const s of specs){get(s,s.name==='client'?'auto-page-size':'auto').click();await wait('actual grouped auto accepted',()=>{const p=pg(s).dataset,g=grid(s);return p.autoPageSize==='true'&&Number(p.pageSize)<12&&g.querySelector('.ix-data-grid-body').getBoundingClientRect().height<=g.clientHeight-g.querySelector('.ix-data-grid-header').getBoundingClientRect().height+2});await page(s,0);const before={...pg(s).dataset},last=(Number(before.end)-1)*3,next=Number(before.end)*3;await focus(cell(s,last,'owner'));key(document.activeElement,'ArrowDown');await focusRow(s,next,'owner');assert(pg(s).dataset.page==='1'&&pg(s).dataset.pageSize===before.pageSize,'auto capacity stays stable through pending navigation and admission');assert(status(s).dataset.selected==='1'&&status(s).dataset.saved==='0'&&!get(s,'tab-across-pages').checked,'selection and separate edit option unchanged');snapshots[s.name+'Auto']={before,after:{...pg(s).dataset}};if(s.name==='client')get(s,'restore').click();else get(s,'reset').click();await wait('fresh Reset clears navigation option',()=>!get(s,'navigate-across-pages').checked&&status(s).dataset.selected==='0'&&(s.name==='client'?pg(s).dataset.enabled==='false':pg(s).dataset.page==='0'&&pg(s).dataset.pageSize==='12'))}
 return{ok:true,snapshots,checks:['client boundary arrows preserve cell/selection lanes; readonly navigation, viewport Page steps and full-query Home/End retain selection without editing','host boundary arrows/Page/Home/End admit only actual accepted current rows and preserve stable selected IDs/lane','client/host grouped navigation skips proven repeated continuation headers and closed pages while retaining real group/header-to-leaf semantics','automatic page handoff preserves accepted capacity/selection and separate editing option; actual Reset clears navigation opt-in'],input:'Excluded synthetic DOM focus/click/input/change/keydown invokes actual shared worklist and synchronous host provider. Accepted DOM focus/page/selection/layout observed only; no application/model/controller/callback/CSS injection. Trusted automated Chromium input is separate evidence. Host known-ancestor skipping is bounded to a continuation; an independent leading header is ordinary. Delayed page_loading/cancellation is verified by actual-component tests, not fabricated here.',renderer:navigator.userAgent};
}catch(error){return{ok:false,error:String(error),snapshots}}
"#;
